# Let's try to solve the 3-coloring problem using pysat
edges = [(0,5), (0,7), (0,9), (0,13), (0,14), (1,2), (2,9), (2,20), (2,23), (3,6), (3,11), (4,8), (4,12), (4,17), (4,18), (4,19), (4,23), (5,6), (5,9), (5,10), (5,14), (5,17), (5,18), (5,21), (6,10), (6,17), (7,22), (8,17), (8,22), (8,24), (9,13), (9,21), (10,12), (10,14), (11,16), (13,20), (13,23), (14,16), (14,23), (14,24), (15,23), (16,19), (16,21), (16,22), (16,23), (17,18), (19,20), (19,23), (19,24), (20,22)]

n = 25
colors = 3

# Try pysat first
try:
    from pysat.solvers import Glucose3
    solver = Glucose3()

    # Variable mapping: x_{v,c} -> v*colors + c + 1 (1-indexed for DIMACS)
    def var(v, c):
        return v * colors + c + 1

    # At least one color per vertex
    for v in range(n):
        solver.add_clause([var(v, c) for c in range(colors)])

    # At most one color per vertex
    for v in range(n):
        for c1 in range(colors):
            for c2 in range(c1+1, colors):
                solver.add_clause([-var(v, c1), -var(v, c2)])

    # Edge constraints: adjacent vertices must have different colors
    for u, v in edges:
        for c in range(colors):
            solver.add_clause([-var(u, c), -var(v, c)])

    sat = solver.solve()
    print("SAT:", sat)
    if sat:
        model = solver.get_model()
        # Extract assignment
        assignment = {}
        for v in range(n):
            for c in range(colors):
                if var(v, c) in model:
                    assignment[v] = c
        print("Assignment:", assignment)
        # Verify
        colors_list = [assignment[v] for v in range(n)]
        ok = True
        for u, v in edges:
            if colors_list[u] == colors_list[v]:
                ok = False
                print("Conflict:", u, v)
        print("Valid:", ok)
        print("Solution:", colors_list)
    else:
        print("UNSAT")
except Exception as e:
    print("Error with pysat:", e)
    # Fallback to pycosat
    try:
        import pycosat
        clauses = []
        for v in range(n):
            clauses.append([var(v, c) for c in range(colors)])
        for v in range(n):
            for c1 in range(colors):
                for c2 in range(c1+1, colors):
                    clauses.append([-var(v, c1), -var(v, c2)])
        for u, v in edges:
            for c in range(colors):
                clauses.append([-var(u, c), -var(v, c)])
        sol = pycosat.solve(clauses)
        print("Pycosat result:", sol)
        if sol != "UNSAT":
            assignment = {}
            for v in range(n):
                for c in range(colors):
                    if var(v, c) in sol:
                        assignment[v] = c
            colors_list = [assignment[v] for v in range(n)]
            print("Solution:", colors_list)
        else:
            print("UNSAT")
    except Exception as e2:
        print("Error with pycosat:", e2)

