# Check girth (length of shortest cycle)
def find_shortest_cycle(start):
    from collections import deque
    dist = {v: -1 for v in range(n)}
    parent = {v: -1 for v in range(n)}
    dist[start] = 0
    q = deque([start])
    while q:
        v = q.popleft()
        for u in adj[v]:
            if dist[u] == -1:
                dist[u] = dist[v] + 1
                parent[u] = v
                q.append(u)
            elif parent[v] != u and parent[u] != v:
                # Found a cycle
                cycle_len = dist[v] + dist[u] + 1
                return cycle_len
    return -1

for v in range(n):
    cycle = find_shortest_cycle(v)
    if cycle > 0:
        print(f"Shortest cycle from {v}: length {cycle}")
